using LocalDeviceToolkit.Core;
using LocalDeviceToolkit.Engine.Deployments;
using LocalDeviceToolkit.Engine.Execution;
using LocalDeviceToolkit.Engine.Planning;
using Xunit;
namespace LocalDeviceToolkit.Tests;
public sealed class DeploymentTests
{
 static readonly DeploymentProfile Profile=new("approved.msi","APP-WIN-001",DeploymentFormat.MachineMsi,"{11111111-2222-3333-4444-555555555555}","1.2.3","Example","Example Ltd",OperationScope.Machine,"x64","setup.msi",new[]{new DeploymentFile("setup.msi",new string('A',64),new string('B',64)),new DeploymentFile("media/data.cab",new string('C',64),null)},TimeSpan.FromMinutes(15));
 static System.Text.Json.JsonElement Parameters=>StrictJson.Value(new DeploymentParameters(Profile.Id,"/fixture/media"));
 static PackageDeploymentOperation Operation(Backend backend,IDeploymentPendingStore store)=>new(new[]{Profile},backend,store);
 static async Task<PlannedAction> Plan(PackageDeploymentOperation op){var before=await op.CaptureBeforeAsync(TestData.Context,Parameters,default);return new(Guid.NewGuid(),new("deployment.example",op.Id,Parameters,new("setup","applications")),await op.InspectAsync(TestData.Context,Parameters,default),before,ObservationFingerprint.Of(before));}
 [Theory][InlineData(0,false,ActionOutcome.AppliedUnverified)][InlineData(0,true,ActionOutcome.AppliedVerified)][InlineData(3010,false,ActionOutcome.RestartRequired)][InlineData(1641,false,ActionOutcome.RestartRequired)][InlineData(1603,false,ActionOutcome.Failed)]
 public async Task Process_exit_requires_fresh_product_identity_and_version(int exit,bool installed,ActionOutcome expected)
 {using var temp=new Temp();var backend=new Backend{Exit=exit,InstalledAfter=installed};var op=Operation(backend,new FileDeploymentPendingStore(temp.Path));var result=await op.ExecuteAsync(TestData.Context,await Plan(op),default);Assert.Equal(expected,result.Outcome);Assert.Equal(1,backend.Starts);Assert.Equal(3,backend.Reads);}
 [Fact] public async Task Timeout_guard_survives_restart_and_never_replays()
 {using var temp=new Temp();var backend=new Backend{End=DeploymentProcessEnd.StillRunning};var op=Operation(backend,new FileDeploymentPendingStore(temp.Path));var plan=await Plan(op);Assert.Equal(ActionOutcome.OutcomeUnknown,(await op.ExecuteAsync(TestData.Context,plan,default)).Outcome);var fresh=Operation(backend,new FileDeploymentPendingStore(temp.Path));Assert.False((await fresh.InspectAsync(TestData.Context,Parameters,default)).CanExecute);Assert.Equal(ActionOutcome.Failed,(await fresh.ExecuteAsync(TestData.Context,plan,default)).Outcome);Assert.Equal(1,backend.Starts);Assert.NotNull(await new FileDeploymentPendingStore(temp.Path).ReadAsync(DeploymentTarget.For(TestData.Context,Profile),default));}
 [Fact] public async Task Unsaved_pending_intent_never_starts_installer()
 {var backend=new Backend();var op=Operation(backend,new FailingPending());await Assert.ThrowsAsync<IOException>(()=>op.ExecuteAsync(TestData.Context,awaitPlan(op),default));Assert.Equal(0,backend.Starts);
 PlannedAction awaitPlan(PackageDeploymentOperation _) => Plan(op).GetAwaiter().GetResult();}
 [Fact] public async Task Source_hash_drift_refuses_launch()
 {using var temp=new Temp();var backend=new Backend();var op=Operation(backend,new FileDeploymentPendingStore(temp.Path));var plan=await Plan(op);backend.InputDigest="changed";Assert.Equal(ActionOutcome.Failed,(await op.ExecuteAsync(TestData.Context,plan,default)).Outcome);Assert.Equal(0,backend.Starts);}
 [Fact] public async Task Machine_deployment_requires_elevated_actual_actor()
 {using var temp=new Temp();var backend=new Backend{Actor=TestData.Actor};var op=Operation(backend,new FileDeploymentPendingStore(temp.Path));Assert.Equal(ActionOutcome.Failed,(await op.ExecuteAsync(TestData.Context,await Plan(op),default)).Outcome);Assert.Equal(0,backend.Starts);}
 [Fact] public void Unknown_fields_and_commands_are_not_parameter_channels()
 {using var temp=new Temp();var op=Operation(new(),new FileDeploymentPendingStore(temp.Path));Assert.Throws<PlanValidationException>(()=>op.ValidateParameters(StrictJson.Value(new{profileId=Profile.Id,sourceDirectory="/fixture",arguments="/anything"})));}
 [Theory][InlineData("../escape.cab")][InlineData("/rooted.cab")][InlineData("media:stream.cab")][InlineData("media\\..\\escape.cab")][InlineData("CON.cab")][InlineData("media/NUL")][InlineData("AUX.txt")][InlineData("COM1.cab")]
 public void Manifest_rejects_escaping_dependencies(string path)=>Assert.Throws<ArgumentException>(()=>DeploymentProfiles.Validate(Profile with{Files=new[]{Profile.Files[0],new DeploymentFile(path,new string('C',64),null)}}));
 [Fact] public void Every_dependency_requires_a_hash_and_entry_requires_a_signer()
 {Assert.Throws<ArgumentException>(()=>DeploymentProfiles.Validate(Profile with{Files=new[]{Profile.Files[0] with{SignerCertificateSha256=null}}}));Assert.Throws<ArgumentException>(()=>DeploymentProfiles.Validate(Profile with{Files=new[]{Profile.Files[0],new DeploymentFile("data.cab","",null)}}));}
 [Fact] public async Task Duplicate_product_claim_is_atomic()
 {using var temp=new Temp();var store=new FileDeploymentPendingStore(temp.Path);var target=DeploymentTarget.For(TestData.Context,Profile);var pending=new DeploymentPending(Guid.NewGuid(),target,TestData.Context.OriginalUserSid,DateTimeOffset.UtcNow,null);await store.ClaimAsync(pending,default);await Assert.ThrowsAsync<IOException>(()=>store.ClaimAsync(pending with{ActionId=Guid.NewGuid()},default));Assert.Equal(pending,await store.ReadAsync(target,default));}
 [Fact] public async Task Detached_bootstrapper_retains_guard_even_after_zero_exit()
 {using var temp=new Temp();var backend=new Backend{Detached=true};var store=new FileDeploymentPendingStore(temp.Path);var op=Operation(backend,store);Assert.Equal(ActionOutcome.OutcomeUnknown,(await op.ExecuteAsync(TestData.Context,await Plan(op),default)).Outcome);Assert.NotNull(await store.ReadAsync(DeploymentTarget.For(TestData.Context,Profile),default));}
 [Fact] public async Task Reconciliation_is_read_only_and_does_not_release_ambiguous_guard()
 {using var temp=new Temp();var backend=new Backend{End=DeploymentProcessEnd.StillRunning};var store=new FileDeploymentPendingStore(temp.Path);var op=Operation(backend,store);await op.ExecuteAsync(TestData.Context,await Plan(op),default);backend.Started=false;backend.Inventory=new(true,true,Profile.ProductIdentity,Profile.Version,"independent fixture");var result=await op.ReconcileAsync(TestData.Context,Parameters,default);Assert.True(result.Inventory.Present);Assert.NotNull(result.Pending);Assert.Equal(1,backend.Starts);Assert.NotNull(await store.ReadAsync(DeploymentTarget.For(TestData.Context,Profile),default));}
 [Fact] public async Task Known_exit_remains_guarded_until_a_matching_durable_run_receipt_is_loaded()
 {using var temp=new Temp();var store=new FileDeploymentPendingStore(temp.Path);var backend=new Backend{InstalledAfter=true};var op=Operation(backend,store);var action=await Plan(op);var result=await op.ExecuteAsync(TestData.Context,action,default);Assert.NotNull(await store.ReadAsync(DeploymentTarget.For(TestData.Context,Profile),default));var schemas=LocalDeviceToolkit.Engine.Evidence.ToolkitEvidenceSchemas.Create();var evidence=new LocalDeviceToolkit.Engine.Evidence.EvidenceStore(System.IO.Path.Combine(temp.Path,"receipts"),schemas,TestData.Context);var run=new RunRecord(Guid.NewGuid(),Guid.NewGuid(),TestData.Context,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,new[]{result},true);await evidence.SaveNewAsync(LocalDeviceToolkit.Engine.Evidence.EvidenceRecord.Create(run.Id,"run",run.Context,run.FinishedAt!.Value,StrictJson.Value(run)),default);await op.AcknowledgeRecordedRunAsync(TestData.Context,Parameters,run.Id,evidence,default);Assert.Null(await store.ReadAsync(DeploymentTarget.For(TestData.Context,Profile),default));}
 [Fact] public async Task An_ambiguous_process_is_not_released_by_a_durable_run_receipt()
 {using var temp=new Temp();var store=new FileDeploymentPendingStore(temp.Path);var backend=new Backend{End=DeploymentProcessEnd.StillRunning};var op=Operation(backend,store);var action=await Plan(op);var result=await op.ExecuteAsync(TestData.Context,action,default);var evidence=new LocalDeviceToolkit.Engine.Evidence.EvidenceStore(System.IO.Path.Combine(temp.Path,"receipts"),LocalDeviceToolkit.Engine.Evidence.ToolkitEvidenceSchemas.Create(),TestData.Context);var run=new RunRecord(Guid.NewGuid(),Guid.NewGuid(),TestData.Context,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,new[]{result},true);await evidence.SaveNewAsync(LocalDeviceToolkit.Engine.Evidence.EvidenceRecord.Create(run.Id,"run",run.Context,run.FinishedAt!.Value,StrictJson.Value(run)),default);await Assert.ThrowsAsync<PlanValidationException>(()=>op.AcknowledgeRecordedRunAsync(TestData.Context,Parameters,run.Id,evidence,default));Assert.NotNull(await store.ReadAsync(DeploymentTarget.For(TestData.Context,Profile),default));}
 [Fact] public async Task Explicit_elevated_resolution_requires_fresh_installed_identity_and_absent_original_process()
 {using var temp=new Temp();var backend=new Backend{Detached=true,InstalledAfter=true,ProcessStatus=DeploymentProcessStatus.NotRunning};var store=new FileDeploymentPendingStore(temp.Path);var op=Operation(backend,store);var action=await Plan(op);await op.ExecuteAsync(TestData.Context,action,default);var schemas=LocalDeviceToolkit.Engine.Evidence.ToolkitEvidenceSchemas.Create();DeploymentEvidenceSchemas.Register(schemas);var evidence=new LocalDeviceToolkit.Engine.Evidence.EvidenceStore(System.IO.Path.Combine(temp.Path,"receipts"),schemas,TestData.Context);var id=await op.ResolveReviewedAsync(TestData.Context,Parameters,new(true),evidence,default);Assert.Null(await store.ReadAsync(DeploymentTarget.For(TestData.Context,Profile),default));Assert.Equal("deployment-resolution",(await evidence.LoadAsync(id,default)).Kind);Assert.Equal(1,backend.Starts);}
 [Theory][InlineData(DeploymentProcessStatus.RunningSameIdentity)][InlineData(DeploymentProcessStatus.Unknown)]
 public async Task Explicit_review_cannot_release_a_running_or_unidentified_installer(DeploymentProcessStatus status)
 {using var temp=new Temp();var backend=new Backend{Detached=true,InstalledAfter=true,ProcessStatus=status};var store=new FileDeploymentPendingStore(temp.Path);var op=Operation(backend,store);await op.ExecuteAsync(TestData.Context,await Plan(op),default);var schemas=LocalDeviceToolkit.Engine.Evidence.ToolkitEvidenceSchemas.Create();DeploymentEvidenceSchemas.Register(schemas);var evidence=new LocalDeviceToolkit.Engine.Evidence.EvidenceStore(System.IO.Path.Combine(temp.Path,"receipts"),schemas,TestData.Context);await Assert.ThrowsAsync<PlanValidationException>(()=>op.ResolveReviewedAsync(TestData.Context,Parameters,new(true),evidence,default));Assert.NotNull(await store.ReadAsync(DeploymentTarget.For(TestData.Context,Profile),default));}
 [Fact] public async Task Machine_guard_resolution_records_new_engineer_without_rewriting_original_requester()
 {using var temp=new Temp();var backend=new Backend{Detached=true,InstalledAfter=true,ProcessStatus=DeploymentProcessStatus.NotRunning};var store=new FileDeploymentPendingStore(temp.Path);var op=Operation(backend,store);await op.ExecuteAsync(TestData.Context,await Plan(op),default);var current=TestData.Context with{OriginalUserSid="S-1-5-21-2000",OriginalUserName="TEST\\second-engineer"};var schemas=LocalDeviceToolkit.Engine.Evidence.ToolkitEvidenceSchemas.Create();DeploymentEvidenceSchemas.Register(schemas);var evidence=new LocalDeviceToolkit.Engine.Evidence.EvidenceStore(System.IO.Path.Combine(temp.Path,"receipts"),schemas,current);var id=await op.ResolveReviewedAsync(current,Parameters,new(true),evidence,default);var receipt=await evidence.LoadAsync(id,default);var resolution=StrictJson.Read<DeploymentResolution>(System.Text.Encoding.UTF8.GetBytes(receipt.Data.GetRawText()));Assert.Equal(current.OriginalUserSid,resolution.Context.OriginalUserSid);Assert.Equal(TestData.Context.OriginalUserSid,resolution.Pending.OriginalUserSid);Assert.Equal(backend.Actor,resolution.ReviewedBy);}
 sealed class Backend:IDeploymentBackend
 {
  public ExecutionActor Actor=TestData.Actor with{IsElevated=true};public int Starts,Reads,Exit;public bool InstalledAfter,Started,Detached;public string InputDigest="verified-inputs";public DeploymentProcessStatus ProcessStatus=DeploymentProcessStatus.Unknown;public DeploymentProcessEnd End=DeploymentProcessEnd.Exited;public DeploymentInventory Inventory=new(true,false,null,null,"fixture inventory");
  public Task<ExecutionActor> GetActorAsync(CancellationToken ct)=>Task.FromResult(Actor);
  public Task<DeploymentInputCheck> CheckInputsAsync(DeploymentProfile profile,string source,CancellationToken ct)=>Task.FromResult(new DeploymentInputCheck(true,InputDigest,"fixture hashes"));
  public Task<DeploymentInventory> ReadInventoryAsync(DeploymentProfile p,DeviceContext c,CancellationToken ct){Reads++;return Task.FromResult(Started&&InstalledAfter?new(true,true,p.ProductIdentity,p.Version,"fresh fixture inventory"):Inventory);}
  public Task<IPreparedDeployment> PrepareAsync(DeploymentProfile p,string source,DeviceContext c,CancellationToken ct)=>Task.FromResult<IPreparedDeployment>(new Prepared(this));
  public Task<DeploymentProcessStatus> InspectProcessAsync(DeploymentProcessObservation? process,CancellationToken ct)=>Task.FromResult(ProcessStatus);
  sealed class Prepared(Backend owner):IPreparedDeployment
  {public string InputDigest=>owner.InputDigest;public ValueTask DisposeAsync()=>ValueTask.CompletedTask;public Task<DeploymentProcessObservation> StartAsync(CancellationToken ct){owner.Starts++;owner.Started=true;return Task.FromResult(new DeploymentProcessObservation(owner.End,42,DateTimeOffset.UtcNow,"fixture-msiexec.exe",owner.End==DeploymentProcessEnd.Exited?owner.Exit:null,owner.Detached));}}
 }
 sealed class FailingPending:IDeploymentPendingStore
 {public Task<DeploymentPending?> ReadAsync(string target,CancellationToken ct)=>Task.FromResult<DeploymentPending?>(null);public Task ClaimAsync(DeploymentPending pending,CancellationToken ct)=>throw new IOException("disk full");public Task ObserveAsync(DeploymentPending pending,CancellationToken ct)=>Task.CompletedTask;public Task CompleteAsync(DeploymentPending pending,CancellationToken ct)=>Task.CompletedTask;}
 sealed class Temp:IDisposable{public string Path{get;}=System.IO.Path.Combine(System.IO.Path.GetTempPath(),Guid.NewGuid().ToString("N"));public void Dispose(){if(Directory.Exists(Path))Directory.Delete(Path,true);}}
}
